var DATA = {"claim": "Drug X lowers BP by 8 mmHg", "checks": "Covariate adjustment|propensity weighting", "data": "8|7|9|8|7|8|9|8|7|8"};
console.log("Claim: " + DATA.claim);
var xs = DATA.data.split("|").map(function (s) { return parseFloat(s); });
function mean(a) { return a.reduce(function (x, y) { return x + y; }, 0) / a.length; }
var m0 = mean(xs);
console.log("Full-sample mean: " + m0.toFixed(3));
// bootstrap: resample with replacement using a deterministic PRNG
var seed = 42;
function rnd() { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; }
var B = 200, means = [];
for (var b = 0; b < B; b++) {
  var s = [];
  for (var i = 0; i < xs.length; i++) s.push(xs[(rnd() * xs.length) | 0]);
  means.push(mean(s));
}
means.sort(function (a, b) { return a - b; });
var lo = means[(0.025 * B) | 0], hi = means[(0.975 * B) | 0];
console.log("Bootstrap 95% CI: [" + lo.toFixed(3) + ", " + hi.toFixed(3) + "]");
console.log("Robustness checks: " + DATA.checks);
var robust = (hi - lo) < Math.abs(m0);
console.log("RESULT: CI width " + (hi - lo).toFixed(3) + " vs |mean| " + Math.abs(m0).toFixed(3) + " — claim " + (robust ? "ROBUST" : "FRAGILE") + ".");

